import (
	"archive/zip"
	"errors"
	"io"
)
func extract(entry *zip.File, output io.Writer) error {
	reader, err := entry.Open()
	if err != nil { return err }
	defer reader.Close()
	const limit = 10 << 20
	written, err := io.CopyN(output, reader, limit+1)
	if err != nil && !errors.Is(err, io.EOF) { return err }
	if written > limit { return errors.New("archive entry exceeds the size limit") }
	return nil
}

